WITH product_totals AS (SELECT product_id, ROUND(AVG(quantity), 2) avg_quantity, SUM(unit_price) total_unit_price FROM order_items WHERE order_id IN (2, 11, 12, 40) GROUP BY product_id) SELECT products.id, products.launch_date, products.product_name, product_totals.avg_quantity, product_totals.total_unit_price FROM products INNER JOIN product_totals ON products.id = product_totals.product_id WHERE product_totals.avg_quantity >= 68 ORDER BY products.id, product_totals.avg_quantity;
